const EMOJI_SKIP = 'svg, script, style, textarea, input, select, option, title';
const EMOJI_RE = new RegExp(`(${Object.keys(LG_ICONS).join('|')})\\uFE0F?([\\u{1F3FB}-\\u{1F3FF}])?(\\u200D)?`, 'gu');

const emojiArt = e => LG_ICONS[String(e || '').replace(/\uFE0F/g, '')] || '';

// For use inside an <svg>: the drawing centred on (x, y), or the plain emoji if there isn't one.
function emojiArtIn(e, x, y, size) {
  const art = emojiArt(e);
  if (!art) return `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="central" font-size="${Math.round(size * 0.8)}">${e}</text>`;
  return art.replace('<svg ', `<svg x="${(x - size / 2).toFixed(1)}" y="${(y - size / 2).toFixed(1)}" width="${size}" height="${size}" `);
}

function swapEmojiText(t) {
  const s = t.nodeValue;
  const parent = t.parentNode;
  if (!s || !parent || parent.nodeType !== 1 || parent.closest(EMOJI_SKIP)) return;
  EMOJI_RE.lastIndex = 0;
  let frag = null, last = 0, m;
  while ((m = EMOJI_RE.exec(s))) {
    if (m[3] || s[m.index - 1] === '\u200D') continue; // part of a longer emoji sequence: leave it alone
    frag = frag || document.createDocumentFragment();
    if (m.index > last) frag.append(s.slice(last, m.index));
    const span = document.createElement('span');
    span.className = 'lg-ic';
    span.setAttribute('aria-hidden', 'true');
    span.innerHTML = LG_ICONS[m[1]];
    frag.append(span);
    last = m.index + m[0].length;
  }
  if (!frag) return;
  if (last < s.length) frag.append(s.slice(last));
  parent.replaceChild(frag, t);
}

function swapEmojiIn(node) {
  if (node.nodeType === 3) { swapEmojiText(node); return; }
  if (node.nodeType !== 1 || node.closest(EMOJI_SKIP) || node.classList.contains('lg-ic')) return;
  const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
  const texts = [];
  for (let n = walker.nextNode(); n; n = walker.nextNode()) texts.push(n);
  texts.forEach(swapEmojiText);
}

new MutationObserver(muts => {
  for (const mu of muts) {
    if (mu.type === 'characterData') swapEmojiText(mu.target);
    else mu.addedNodes.forEach(swapEmojiIn);
  }
}).observe(document.documentElement, { childList: true, characterData: true, subtree: true });
if (document.body) swapEmojiIn(document.body);
